export const REQUIRED_SECRETS = [
  "SUPABASE_SECRET_KEY",
  "MP_ACCESS_TOKEN",
  "MP_WEBHOOK_SECRET",
] as const;

// Generated by Wrangler; optional here because readConfig validates missing bindings.
export type Bindings = Partial<WorkerBindings>;

export interface Config {
  environment: "local" | "staging" | "production";
  origins: string[];
  paymentsEnabled: boolean;
  checkoutPro?: { returnOrigin: string; webhookUrl: string; collectorId: string };
}

function isLoopback(url: URL): boolean {
  return ["localhost", "127.0.0.1", "[::1]"].includes(url.hostname);
}

function originUrl(value: string): URL {
  const url = new URL(value);
  if (url.origin !== value || url.username || url.password || url.hostname.includes("*")) throw new Error();
  return url;
}

/** Never attach bindings, values or parser errors to this error. */
export function readConfig(env: Bindings): Config {
  try {
    const environment = env.APP_ENV;
    if (!["local", "staging", "production"].includes(environment ?? "")) throw new Error();
    if (!["false", "true"].includes(env.PAYMENTS_ENABLED ?? "")) throw new Error();
    // This delivery only supports sandbox activation; production rollout is separate.
    if (env.PAYMENTS_ENABLED === "true" && environment !== "staging") throw new Error();
    const origins = (env.ALLOWED_ORIGINS ?? "").split(",").map((s) => s.trim());
    if (!origins.length || origins.some((s) => !s)) throw new Error();
    for (const value of origins) {
      const url = originUrl(value);
      if (environment === "local") {
        if (!isLoopback(url) || !["http:", "https:"].includes(url.protocol)) throw new Error();
      } else if (url.protocol !== "https:" || isLoopback(url)) {
        throw new Error();
      }
    }
    if (environment !== "local") {
      const supabase = originUrl(env.SUPABASE_URL ?? "");
      if (supabase.protocol !== "https:" || isLoopback(supabase)) throw new Error();
      if (!env.SUPABASE_PUBLISHABLE_KEY?.trim()) throw new Error();
      if (REQUIRED_SECRETS.some((name) => !env[name]?.trim())) throw new Error();
    }
    let checkoutPro: Config["checkoutPro"];
    if (env.CHECKOUT_PRO_MODE) {
      if (env.CHECKOUT_PRO_MODE !== "sandbox" || environment !== "staging") throw new Error();
      const returnOrigin = originUrl(env.CHECKOUT_RETURN_ORIGIN ?? "");
      const webhook = new URL(env.CHECKOUT_WEBHOOK_URL ?? "");
      if (!origins.includes(returnOrigin.origin) || returnOrigin.protocol !== "https:" ||
        webhook.protocol !== "https:" || webhook.username || webhook.password || webhook.search || webhook.hash ||
        webhook.pathname !== "/webhooks/mercadopago" || isLoopback(webhook) ||
        !/^\d{1,20}$/.test(env.MP_COLLECTOR_ID ?? "")) throw new Error();
      checkoutPro = { returnOrigin: returnOrigin.origin, webhookUrl: webhook.href, collectorId: env.MP_COLLECTOR_ID! };
    }
    if (env.PAYMENTS_ENABLED === "true" && !checkoutPro) throw new Error();
    return { environment: environment as Config["environment"], origins: [...new Set(origins)],
      paymentsEnabled: env.PAYMENTS_ENABLED === "true", checkoutPro };
  } catch {
    throw new Error("CONFIGURATION_INVALID");
  }
}
